internal class GUPPriceEngineDecoratedAdjustmentValueLine extends GUPPriceEngineAbstractDecoratedLine
{
    real adjustmentValue;
    Price computedPrice;

}

Method.Source:
private void new (real _adjustmentValue,
        GUPPriceEngineAbstractLine _line)
{
    this.adjustmentValue = _adjustmentValue;
    super(_line);
}

public static GUPPriceEngineDecoratedAdjustmentValueLine newInstanceByAdjustmentValueAndLine(
    real _adjustmentValue,
    GUPPriceEngineMarginCodeLine _line)
{
    return new GUPPriceEngineDecoratedAdjustmentValueLine(
        _adjustmentValue, 
        _line);
}

public Price parmComputedPrice(boolean _update = false, Price _computedPrice = 0)
{
    if (_update)
    {
        this.computedPrice = _computedPrice;
    }

    return this.computedPrice;
}
